-- V2: REFERENCE DATA + FICTIONAL RENTAL DEMO (MySQL 8).
-- Originally prepared as V15; aligned with the current V1 full-schema / V2 seed chain.
-- Schema prerequisite: current Property/Room schema, as built by V1__fullsql.sql.
-- This file seeds DATA ONLY; it does not create or replace persistent tables.
-- Official administrative snapshot as of 2026-10-27, direct two-tier hierarchy:
-- 34 provinces/cities, 3321 communes/wards/special zones (2599 xa / 709 phuong / 13 dac khu).
-- Source: https://danhmuchanhchinh.nso.gov.vn/
-- Export: Cap=Xa; Den ngay=27/10/2026; Thuc Hien -> Xuat Excel (all rows).
-- Original XLS SHA256: d4a8ece8c02334bd428b661d835357c6736ad2646ac32f473707b0842fe6895a
-- Legal base: QD 19/2025/QD-TTg; current names include NQ 30,36,39/2026/QH16.
-- Official codes are STRINGS: preserve 2-digit province and 5-digit ward leading zeros.
-- No district table: wards include xa, phuong and dac khu, directly under provinces.
-- Demo users/properties are fictional; .test emails, NULL phone/CCCD/coordinates.
-- All five demo accounts initially use: TroTotDemo@2026 (BCrypt cost 10).
-- Existing account passwords/auth_version and edited demo asset values are preserved.
-- No Listing is seeded: private assets appear publicly only after posting/approval.
-- Current Flyway chain: V1__fullsql.sql -> V2__seed_reference_and_demo_data.sql.
-- See docs/SEED_V15.md for sources, demo credentials and verification.


