-- 3. OFFICIAL ADMINISTRATIVE REFERENCES (snapshot 2026-10-27).
-- Reference names/parent associations synchronize by official code; existing IDs stay intact.
-- No old address record is deleted, no user Property is moved to an inferred address.
-- Temporary staging exists only on this connection and is dropped at the end.
