INSERT INTO wards (id, province_id, code, name)
SELECT s.id, p.id, s.code, s.name FROM v15_ward_seed s JOIN provinces p ON p.code=s.province_code
ON DUPLICATE KEY UPDATE province_id=VALUES(province_id), name=VALUES(name);
DROP TEMPORARY TABLE v15_ward_seed;
DROP TEMPORARY TABLE v15_province_seed;


-- 4. PROPERTY TYPES describe the building/site, not a room size or furniture feature.

INSERT INTO property_types (id, name, description)
SELECT '5d67dece-5541-54d5-99ba-4f655ef68c2a', 'Nhà trọ', 'Cơ sở gồm các phòng trọ cho thuê riêng; tiện ích chung quản lý tại cơ sở.'
